seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# 1. Direct repeats >= 12 bp
def find_direct_repeats(s, minlen=12):
    hits=[]
    for L in range(minlen, 21):
        seen={}
        for i in range(len(s)-L+1):
            k=s[i:i+L]
            if k in seen:
                hits.append((L,seen[k],i,k))
            else:
                seen[k]=i
    return hits

# 2. Inverted repeats (palindromic stems) >= 8 bp, loop 3-20
def find_inverted(s, minstem=8, minloop=3, maxloop=20):
    hits=[]
    for i in range(len(s)):
        for L in range(minstem, 15):
            stem=s[i:i+L]
            if i+L+minloop+ L > len(s): break
            for loop in range(minloop, maxloop+1):
                j=i+L+loop
                if j+L>len(s): break
                if s[j:j+L]==rc(stem):
                    hits.append((L,loop,i,j+L))
    return hits

